def get_season_name(monthcode, region):
    """
    Determines the season for a given month and region.

    Args:
        monthcode (int): Month number (1-12).
        region (str): Region ('US', 'Australia', 'India').

    Returns:
        str: Season name or error message.
    """
    # Validate region
    if region not in ['US', 'Australia', 'India']:
        return "Error: Region 'Canada' is not supported. Please choose from US, Australia, India."

    # Validate monthcode
    if not isinstance(monthcode, int) or monthcode < 1 or monthcode > 12:
        return "Error: Invalid month code. Please enter a value between 1 and 12."

    # Define seasonal mappings
    us_seasons = {
        12: 'Winter', 1: 'Winter', 2: 'Winter',
        3: 'Spring', 4: 'Spring', 5: 'Spring',
        6: 'Summer', 7: 'Summer', 8: 'Summer',
        9: 'Autumn', 10: 'Autumn', 11: 'Autumn'
    }

    au_seasons = {
        12: 'Summer', 1: 'Summer', 2: 'Summer',
        3: 'Autumn', 4: 'Autumn', 5: 'Autumn',
        6: 'Winter', 7: 'Winter', 8: 'Winter',
        9: 'Spring', 10: 'Spring', 11: 'Spring'
    }

    in_seasons = {
        12: 'Winter', 1: 'Winter', 2: 'Winter',
        3: 'Summer', 4: 'Summer', 5: 'Summer',
        6: 'Monsoon', 7: 'Monsoon', 8: 'Monsoon',
        9: 'Autumn', 10: 'Autumn', 11: 'Autumn'
    }

    # Return season based on region and month
    if region == 'US':
        return us_seasons.get(monthcode)
    elif region == 'Australia':
        return au_seasons.get(monthcode)
    elif region == 'India':
        return in_seasons.get(monthcode)
