def common_factors(a, b):
    if a < 1 or b < 1:
        return []

    # Find GCD to limit search range
    import math
    gcd_val = math.gcd(a, b)

    # Find all factors of the GCD
    factors = []
    i = 1
    while i * i <= gcd_val:
        if gcd_val % i == 0:
            factors.append(i)
            if i != gcd_val // i:
                factors.append(gcd_val // i)
        i += 1

    return sorted(factors)
