import calendar

def format_date_list(date_list):
    """
    Format a list of (year, month, day) tuples into "YYYY-MM-DD" strings.
    Validates each date and raises ValueError on invalid input.
    """
    for i, (year, month, day) in enumerate(date_list):
        # Validate month and day
        if month < 1 or month > 12:
            raise ValueError(f"Invalid date: ({year}, {month}, {day})")
        if day < 1:
            raise ValueError(f"Invalid date: ({year}, {month}, {day})")

        # Validate against calendar (handles leap years and max days per month)
        if not calendar.isleap(year):
            max_day = calendar.monthrange(year, month)[1]
        else:
            max_day = 29

        if day > max_day:
            raise ValueError(f"Invalid date: ({year}, {month}, {day})")

    return [f"{y}-{m:02d}-{d:02d}" for y, m, d in date_list]
